# Write a ViennaRNA-based search script
import RNA
import random

target = "((((((((((((((.((((((...........((((((((((((.....((((((((....(((((((((((((........))))))))))....))))))))....))))))....)))))...((((((.......))))))))))............)))))).))))....))))))...))))..."
n = len(target)

# pair map
stack=[];pairs={}
for i,c in enumerate(target):
    if c=='(':stack.append(i)
    elif c==')':j=stack.pop();pairs[j]=i;pairs[i]=j

def gc(s): return (s.count('G')+s.count('C'))/len(s)

def fold(s):
    fc=RNA.fold_compound(s)
    fc.pf()
    ss,mfe=fc.mfe()
    return ss

def dist(a,b):
    return sum(1 for x,y in zip(a,b) if x!=y)

def cost(s):
    ss=fold(s)
    d=dist(ss,target)
    return d

def random_init():
    s=['A']*n
    for i in range(n):
        if i in pairs:
            j=pairs[i]
            if i<j:
                pair=random.choice(['GC','CG','AU','UA'])
                s[i]=pair[0]; s[j]=pair[1]
    return ''.join(s)

def mutate(s, k=3):
    s=list(s)
    for _ in range(k):
        i=random.randrange(n)
        s[i]=random.choice('ACGU')
    return ''.join(s)

def targeted_repair(s, ss):
    # strengthen missing pairs, break spurious
    s=list(s)
    # missing pairs: make complementary
    for i in range(n):
        if target[i]=='(' and i in pairs:
            j=pairs[i]
            if ss[i]!='(' or ss[j]!=')':
                # choose GC
                s[i]='G'; s[j]='C'
    return ''.join(s)

best=None;bestd=999
random.seed(42)
import sys
for trial in range(40):
    s=random_init()
    for it in range(400):
        cur=cost(s)
        if cur==0:
            print("SOLVED",s)
            sys.exit(0)
        if cur<bestd:
            bestd=cur;best=s
        # targeted: take missing pairs, swap to GC
        ss=fold(s)
        s2=list(s)
        improved=False
        for i in range(n):
            if target[i]=='(' and i in pairs:
                j=pairs[i]
                if ss[i]!='(' or ss[j]!=')':
                    # try making strong pair
                    cand=['GC','CG']
                    for p in cand:
                        t=list(s2); t[i]=p[0]; t[j]=p[1]
                        if cost(''.join(t))<cur:
                            s2=t; improved=True; break
        if improved:
            s=''.join(s2)
        else:
            s=mutate(s,2)
    print("trial",trial,"bestd",bestd, flush=True)
print("BEST",best,bestd)
